import json,pathlib,hashlib,datetime,re
from zoneinfo import ZoneInfo
R=pathlib.Path(__file__).resolve().parents[3];D=pathlib.Path(__file__).resolve().parent
acq=json.loads((R/'docs/acquisition/new-gpt-20261108-62.json').read_text());rows=acq['downloadedImages'];bank=json.loads((R/'site/dist/data.json').read_text())['questions'];flat=[c for q in bank for c in q.get('groupQuestions') or [q]]
def save(p,v):p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
manifest={'sourceId':'src-more-062','items':[]}
def add(index,num,title,stem,opts,correct,explanations,explanation,passage='',tables=None,student='',review=None,tags=None):
 ident=f'q-{979+index*3}';row=rows[index];date=datetime.datetime.fromtimestamp(row['firstQuestionTimestamp'],ZoneInfo('Asia/Taipei')).date().isoformat();crop=D/f'evidence/q-{num}-original.png'
 q=dict(id=ident,sourceId='src-more-062',subject='Chinese',title=f'國文第{num}題｜'+title,chapter='綜合',volume='綜合',date=date,dateLabel='首次出題日期',addedAt='2026-11-08',question=stem+'\n'+'\n'.join(f'({l}) {t}' for l,t in zip('ABCD',opts)),answer=f'({correct}) {opts["ABCD".index(correct)]}',explanation=explanation,trap='',verification='原卷逐題核對',verificationNote='已實開真正上傳原卷及本題裁圖，逐題核對題幹、全部選項與必要閱讀材料。未提供實際考試日期，日期採首次使用者出題訊息的台灣日期；無教材冊章證據，歸綜合。',diagram='',notes='',status='todo',starred=False,tags=tags or [],images=[str(crop.relative_to(R))],sourceLabel=f'分享原卷｜第{num}題',studentAnswer=student,contentStatus='完整原題',correctOption=correct,passage=passage,optionAnalysis=[dict(label=l,text=t,wordClass='應選' if l==correct else '不選',meaning='',explanation=e) for l,t,e in zip('ABCD',opts,explanations)],tables=tables or [],questionFigures=[],explanationFigures=[],originalQuestionNumber=str(num),sourceEvidence=dict(url=acq['url'],messageId=row['messageId'],firstQuestionTimestamp=row['firstQuestionTimestamp'],firstQuestionDateTime=datetime.datetime.fromtimestamp(row['firstQuestionTimestamp'],ZoneInfo('Asia/Taipei')).isoformat(),originals=[{k:row[k] for k in ['fileId','path','sha256','bytes']}],inclusionEvidence=f'使用者明示{num}@錯題；本題範圍有原卷紅筆訂正，已實開核對。',cropSHA256=sha(crop)))
 candidates=[dict(id=x['id'],title=x['title']) for x in flat if any(w in x.get('question','')+x.get('passage','') for w in tags or [])]
 dup=dict(exactMatch=False,candidateCount=len(candidates),candidates=candidates[:20],method='question_index文字候選＋正式題庫/所有groupQuestions題幹及完整選項比對，核對必要原卷，未見同一題；相近主題不併題。')
 qpath=D/f'{ident}.json';save(qpath,q)
 rv=dict(id=ident,reviewerAgent='/root/comic_lane_2',originalVisualChecked=True,completeOriginalAndOptions=True,sourceGeneratedArtUsed=False,actualViewed=[row['path'],str(crop.relative_to(R))],duplicateReview=dup,inclusionEvidence=q['sourceEvidence']['inclusionEvidence'],sourceUrl=acq['url'],originalQuestionNumber=str(num),checkedAt=datetime.datetime.now(datetime.timezone.utc).isoformat(),correction=review)
 rpath=D/f'{ident}-review.json';save(rpath,rv)
 manifest['items'].append(dict(id=ident,status='ready',questionPath=str(qpath.relative_to(R)),questionSHA256=sha(qpath),reviewPath=str(rpath.relative_to(R)),reviewSHA256=sha(rpath)))
 save(D/'manifest.json',manifest)
add(0,4,'用字辨正：貧瘠、狡詐與舶來品','下列文句，何者用字完全正確？',['土壤貧瘠的村落裡，居民皆面黃肌瘦','這人陰險狡許，與他來往必須有所防範','此商圈緊鄰港口，曾因販售泊來品而興盛','他們曾是形影不離的戀人，如今卻視同末路'],'A',['「貧瘠」指土地不肥沃；「面黃肌瘦」形容面色發黃、身體消瘦，兩者用字正確。','原卷印「狡許」，應為「狡詐」，形容狡猾奸詐；不能把原題字形改成正字後再判B正確。','「泊來品」應為「舶來品」；舶指大船，舶來品指從國外輸入的物品。','「視同末路」應為「視同陌路」，意思是當作不相識的人；末路則指路的盡頭或窮困失意的處境。'],'選A。先依原卷逐字辨認，再核對詞語。A的「貧瘠」「面黃肌瘦」均正確；B原印「狡許」應作「狡詐」；C「泊來品」應作「舶來品」；D「視同末路」應作「視同陌路」。\n\n原AI把A正確的「貧瘠」讀成「貧脊」，又把B的錯字直接讀成「狡詐」，因此誤選B。本題保留原印文字，訂正為A，並將辨字及答案差異列入核對。',student='原卷藍筆字母被紅筆覆蓋，無法可靠辨識；紅筆訂正A。',review=dict(reason='原AI讀錯A、B字形而誤判答案。',before='AI選B；稱A印貧脊、B印狡詐。',after='依原卷保留A貧瘠、B狡許；答案A，B狡許應訂正狡詐。',sourceAIMessageIndices=[34,48,49]),tags=['用字辨正','貧瘠','舶來品'])
add(1,6,'進球紀錄與標點斷句','下表是地球盃足球賽第一場資格賽的進球紀錄。堂安根據進球紀錄撰寫報導，下列標點符號的使用，何者最恰當？',['A隊資格賽首戰，B隊無法守住，領先下半場遭到逆轉，最終便以1比2落敗。','A隊資格賽首戰B隊，無法守住領先，下半場遭到逆轉，最終便以1比2落敗。','A隊資格賽首戰，B隊無法守住領先，下半場遭到逆轉。最終，便以1比2落敗。','A隊資格賽首戰B隊，無法守住、領先，下半場遭到逆轉，最終便以1比2落敗。'],'B',['「首戰B隊」與「守住領先」皆為完整語意，被不當切開；還容易誤把B隊當作落敗主詞。','以A隊為主詞，先交代對手B隊，再說明A隊無法守住領先、下半場遭逆轉及1比2落敗，符合原表。','把「首戰B隊」切斷，容易變成B隊先領先、被逆轉，與表格不符；「最終，便」也不必如此分割。','守住和領先不是並列事項，「守住領先」不能用頓號分開。'],'選B。表格顯示A隊在上半場先進一球，B隊在下半場連進兩球，終場比數為A隊1、B隊2。報導應持續以A隊為主詞，描述A隊先領先、後被逆轉而落敗。\n\n「首戰B隊」表示第一戰對手是B隊，「守住領先」表示維持領先優勢，都不能任意用標點拆開。頓號用於並列詞語，D把「守住、領先」分開，破壞原本語意。',tables=[dict(caption='進球紀錄',headers=['進球時間','得分隊伍','進球球員背號'],rows=[['上半場19分46秒','A隊','9號'],['下半場37分20秒','B隊','9號'],['下半場42分53秒','B隊','7號']])],student='原卷藍筆C，紅筆訂正B。',tags=['標點符號','進球紀錄'])
add(2,12,'成語與語境：目空一切','杜總編檢視雜誌的運勢專欄，發現專欄中多處用詞不當，僅有一處正確。下列文句「　」中的成語，何者使用最恰當？',['財富：投資方面有可能出現「胸無城府」的危機，請務必謹慎','交友：勿在朋友面前誇耀自己，以免被當成「目空一切」之人','學習：無論是學問或技藝，皆有機會達到「眼高手低」的境界','愛情：發生爭執時應自我反省，降低彼此「口吐珠璣」的可能'],'B',['胸無城府形容為人坦率、沒有心機，不是投資損失或財務危機。','目空一切指驕傲自大、看不起他人，與告誡不要在朋友面前誇耀自己的語境相合。','眼高手低指標準或想法很高，實際能力卻不足，是貶義詞，不能當成值得追求的境界。','口吐珠璣形容說話或文章優美、有價值，不是爭執時惡言相向。'],'選B。成語使用要同時核對詞義、感情色彩和上下文。「目空一切」形容高傲、自以為了不起，正好呼應不要誇耀自己的提醒。\n\nA把坦率無心機誤作財務危機；C把能力不足的貶義成語當作值得達到的境界；D把優美有價值的言詞誤當爭吵傷人的話。',student='原卷藍筆D，紅筆訂正B。',tags=['成語','目空一切'])
add(3,18,'〈寫詩無用論〉的煉字與價值對比','關於這首詩的分析，下列敘述何者最恰當？',['將寫詩比喻為煉丹，指出寫詩需要耗時費力才能得到成果','透過出售場所的對比，凸顯藝術作品具有雅俗共賞的特質','運用倒反手法肯定畫作價值，說明繪畫比文學更受到世人重視','以作畫呼應寫詩，強調無論素材取自何處，皆可成為藝術創作'],'A',['鉛字投入丹爐、七七四十九日，將文字創作比喻為費時煉丹，符合詩句。','市場與拍賣場的對照呈現價值判定及價格的反差，不能由此推得雅俗共賞。','詩中沒有以相反語意表達肯定的倒反手法；不能只因畫作高價成交就接受整個選項。','詩中是從垃圾桶撿到一幅畫，沒有描寫如何作畫，也沒有談創作素材來源。'],'選A。「一堆鉛字」象徵文字，「投入丹爐」「七七四十九日」將寫詩的鍛鍊字句比喻為煉丹，具體表現耗費時間與心力。後半節以垃圾桶撿到的畫作在拍賣場高價落槌，形成藝術價值與市場價格的反差。\n\nB所說雅俗共賞不是詩中對比的重點；C把題目沒有運用的「倒反手法」套入，不能因部分描述價差就判整項正確；D更把「撿到畫」誤作「作畫」。原AI選C並誤認倒反，依完整詩句與選項訂正A。',passage='寫詩無用論　辛牧\n\n把一堆鉛字投入丹爐中\n七七四十九日後\n在市場以斤兩兜售\n\n在垃圾桶撿到一幅畫\n在蘇富比\n以數十百萬英鎊落槌\n\n註：蘇富比：國際上歷史最久、最具規模的拍賣公司，所拍賣的項目有繪畫、書畫、瓷器、珠寶、珍玩等。',student='原卷藍筆B，紅筆訂正A。',review=dict(reason='原AI選C，將價格反差誤判為倒反手法。',before='AI答案C，稱運用倒反肯定畫作價值。',after='答案A；鉛字投入丹爐及四十九日對應費時煉字；C並非倒反手法。',sourceAIMessageIndices=[103]),tags=['現代詩','寫詩無用論','比喻'])
print('Prepared',len(manifest['items']),'questions')
